const crypto = require('crypto');

return items.map(item => {
  const content = (item.json.content || '').trim();
  const sourceId = item.json.fileId || item.json.source_id || item.json.metadata?.fileId;
  const chunkIndex = item.json.chunk_index ?? item.json.metadata?.chunk_index ?? item.json.metadata?.chunk ?? 0;

  // dedupe within the same file
  const contentHash = crypto.createHash('sha256').update(content).digest('hex');

  item.json.source_id = sourceId;
  item.json.chunk_index = chunkIndex;
  item.json.content = content;
  item.json.content_hash = contentHash;

  return item;
});
